/**
 * Note editor — title, folder, textarea/preview, append-from-page, delete.
 *
 * Auto-save: label / content / folder_name changes flush to Supabase ~600ms
 * after the last keystroke. Appends from page-extract bypass the debounce
 * and persist immediately so the new content lands in the textarea
 * deterministically.
 *
 * Optimistic UX: the React Query detail cache is updated on every save so
 * a quick "open list → re-open this note" reflects the latest content even
 * before the next list refetch.
 */

import { MarkdownView } from '@/components/MarkdownView';
import { getNote, softDeleteNote, updateNote } from '@/lib/notes/queries';
import type { NoteListItem } from '@/lib/notes/types';
import { formatRelativeTime, uniqueFolderNames } from '@/lib/notes/utils';
import { useNotesUiStore } from '@/state/notes';
import { ConfirmDialog } from '@ai-matrx/design-system';
import { Button, BasicInput as Input, Skeleton } from '@ai-matrx/design-system';
import { BasicTextarea as Textarea } from '@ai-matrx/design-system';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { ArrowLeft, Eye, Pencil, Trash2 } from 'lucide-react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AppendFromPagePanel } from './AppendFromPagePanel';

const SAVE_DEBOUNCE_MS = 600;
const FOLDERS_LIST_ID = 'matrx-notes-folder-suggestions';

interface DraftState {
  label: string;
  content: string;
  folderName: string;
}

function sameDraft(a: DraftState | null, b: DraftState | null): boolean {
  return (
    !!a && !!b && a.label === b.label && a.content === b.content && a.folderName === b.folderName
  );
}

// Keep unsaved edits available when switching notes while a write fails. This
// lives only in the sidepanel process; successful persistence removes the draft.
const unsavedDrafts = new Map<string, DraftState>();

export function NoteEditor({ noteId }: { noteId: string }) {
  const queryClient = useQueryClient();
  const setSelectedNoteId = useNotesUiStore((s) => s.setSelectedNoteId);
  const viewMode = useNotesUiStore((s) => s.viewMode);
  const setViewMode = useNotesUiStore((s) => s.setViewMode);

  const detailQuery = useQuery({
    queryKey: ['notes', 'detail', noteId],
    queryFn: () => getNote(noteId),
    staleTime: 30_000,
    retry: false,
  });

  const note = detailQuery.data ?? null;

  const [draft, setDraft] = useState<DraftState | null>(null);
  const [savingState, setSavingState] = useState<'idle' | 'saving' | 'saved' | 'error' | 'unsaved'>(
    'idle',
  );
  const [lastSavedAt, setLastSavedAt] = useState<string | null>(null);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [deleteFailed, setDeleteFailed] = useState(false);
  const draftRef = useRef<DraftState | null>(null);
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inflightRef = useRef<Promise<void> | null>(null);
  const queuedRef = useRef<DraftState | null>(null);
  const savedRef = useRef<DraftState | null>(null);
  const failedRef = useRef(false);
  const mountedRef = useRef(true);
  const deletedRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  // Reset draft when noteId changes (user opened a different note).
  // Must be declared BEFORE the seed-from-note effect: on mount, both effects
  // run in declaration order, and when detailQuery serves cached data
  // synchronously (e.g. re-opening a note seen earlier in the session), the
  // seed effect would otherwise populate draft and then this reset would
  // immediately clobber it — leaving the editor stuck on the skeleton.
  useEffect(() => {
    deletedRef.current = false;
    draftRef.current = null;
    savedRef.current = null;
    queuedRef.current = null;
    setDraft(null);
    setSavingState('idle');
    setLastSavedAt(null);
    if (saveTimerRef.current) {
      clearTimeout(saveTimerRef.current);
      saveTimerRef.current = null;
    }
  }, [noteId]);

  // Hydrate draft from server data the first time it lands. After that, the
  // user owns the draft until they switch notes — server pushes don't clobber
  // local edits (no realtime in v1, so this is a non-issue in practice).
  useEffect(() => {
    if (!note) return;
    if (draftRef.current === null) {
      const seed: DraftState = {
        label: note.label ?? '',
        content: note.content ?? '',
        folderName: note.folder_name ?? '',
      };
      savedRef.current = seed;
      const recovered = unsavedDrafts.get(noteId);
      const initial = recovered ?? seed;
      setDraft(initial);
      draftRef.current = initial;
      if (recovered && !sameDraft(recovered, seed)) setSavingState('unsaved');
      else unsavedDrafts.delete(noteId);
      setLastSavedAt(note.updated_at);
    }
  }, [note, noteId]);

  const allNotes = queryClient.getQueryData<NoteListItem[]>(['notes', 'list']) ?? [];
  const folderSuggestions = useMemo(() => uniqueFolderNames(allNotes), [allNotes]);

  const persist = useCallback(
    async (snapshot: DraftState) => {
      if (deletedRef.current) return;
      queuedRef.current = snapshot;
      failedRef.current = false;
      if (inflightRef.current) return inflightRef.current;
      const drain = async () => {
        while (queuedRef.current && !deletedRef.current) {
          const writing = queuedRef.current;
          queuedRef.current = null;
          if (sameDraft(writing, savedRef.current)) {
            if (sameDraft(unsavedDrafts.get(noteId) ?? null, writing)) unsavedDrafts.delete(noteId);
            if (mountedRef.current && sameDraft(draftRef.current, writing) && !queuedRef.current) {
              setSavingState('saved');
            }
            continue;
          }
          if (mountedRef.current) setSavingState('saving');
          let updated: Awaited<ReturnType<typeof updateNote>> = null;
          try {
            updated = await updateNote(noteId, {
              label: writing.label.trim() || 'Untitled',
              content: writing.content,
              folder_name: writing.folderName.trim() ? writing.folderName.trim() : null,
            });
          } catch (error) {
            console.warn('[notes] autosave failed', error);
          }
          if (deletedRef.current) return;
          const latest = queuedRef.current ?? draftRef.current ?? writing;
          if (!updated) {
            unsavedDrafts.set(noteId, latest);
            if (!sameDraft(latest, writing)) {
              queuedRef.current = latest;
              continue;
            }
            queuedRef.current = latest;
            failedRef.current = true;
            if (mountedRef.current) setSavingState('error');
            return;
          }
          savedRef.current = writing;
          queryClient.setQueryData(['notes', 'detail', noteId], updated);
          void queryClient.invalidateQueries({ queryKey: ['notes', 'list'] }).catch((error) => {
            console.warn('[notes] list refresh after autosave failed', error);
          });
          if (!sameDraft(latest, writing)) {
            queuedRef.current = latest;
            continue;
          }
          if (sameDraft(unsavedDrafts.get(noteId) ?? null, writing)) unsavedDrafts.delete(noteId);
          if (mountedRef.current) {
            setLastSavedAt(updated.updated_at);
            setSavingState('saved');
          }
        }
      };
      const running = drain().finally(() => {
        inflightRef.current = null;
        if (queuedRef.current && !failedRef.current) void persist(queuedRef.current);
      });
      inflightRef.current = running;
      return running;
    },
    [noteId, queryClient],
  );

  const scheduleSave = useCallback(
    (next: DraftState) => {
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
      saveTimerRef.current = setTimeout(() => {
        saveTimerRef.current = null;
        void persist(next);
      }, SAVE_DEBOUNCE_MS);
    },
    [persist],
  );

  const updateDraft = useCallback(
    (patch: Partial<DraftState>) => {
      if (!draftRef.current) return;
      const next = { ...draftRef.current, ...patch };
      draftRef.current = next;
      setDraft(next);
      unsavedDrafts.set(noteId, next);
      setSavingState('saving');
      scheduleSave(next);
    },
    [noteId, scheduleSave],
  );

  // Flush pending edits on unmount so a quick switch-and-back doesn't lose typing.
  useEffect(
    () => () => {
      if (deletedRef.current) return;
      if (saveTimerRef.current) {
        clearTimeout(saveTimerRef.current);
        saveTimerRef.current = null;
        if (draftRef.current) void persist(draftRef.current);
      }
    },
    [persist],
  );

  const onAppend = useCallback(
    async (next: string) => {
      if (!draftRef.current) return;
      // Cancel any pending debounced save — we're persisting now.
      if (saveTimerRef.current) {
        clearTimeout(saveTimerRef.current);
        saveTimerRef.current = null;
      }
      const updatedDraft = { ...draftRef.current, content: next };
      draftRef.current = updatedDraft;
      setDraft(updatedDraft);
      unsavedDrafts.set(noteId, updatedDraft);
      setSavingState('saving');
      await persist(updatedDraft);
    },
    [noteId, persist],
  );

  const performDelete = async () => {
    setDeleteOpen(false);
    if (deleting) return;
    setDeleting(true);
    setDeleteFailed(false);
    try {
      const ok = await softDeleteNote(noteId);
      if (!ok) {
        setDeleteFailed(true);
        return;
      }
      deletedRef.current = true;
      if (saveTimerRef.current) {
        clearTimeout(saveTimerRef.current);
        saveTimerRef.current = null;
      }
      queuedRef.current = null;
      unsavedDrafts.delete(noteId);
      queryClient.setQueryData<NoteListItem[]>(['notes', 'list'], (current) =>
        current?.filter((item) => item.id !== noteId),
      );
      setSelectedNoteId(null);
      void queryClient.invalidateQueries({ queryKey: ['notes', 'list'] }).catch((error) => {
        console.warn('[notes] list refresh after delete failed', error);
      });
    } catch (error) {
      console.warn('[notes] delete action failed', error);
      setDeleteFailed(true);
    } finally {
      setDeleting(false);
    }
  };

  const onBack = () => setSelectedNoteId(null);

  if (!note && !draft && !detailQuery.isPending) {
    return (
      <div className="flex h-full flex-col">
        <div className="flex shrink-0 items-center border-b border-border/50 px-3 py-2">
          <Button size="sm" variant="ghost" className="h-7 gap-1 px-2 text-xs" onClick={onBack}>
            <ArrowLeft className="size-3.5" /> Back
          </Button>
        </div>
        <div
          className="flex flex-1 flex-col items-center justify-center gap-3 p-4 text-center"
          role="alert"
        >
          <p className="text-sm font-medium">
            {detailQuery.isError ? 'Could not load this note.' : 'This note is unavailable.'}
          </p>
          <p className="text-xs text-muted-foreground">
            {detailQuery.isError
              ? 'Please try again.'
              : 'It may have been deleted or access may have changed.'}
          </p>
          <Button type="button" size="sm" onClick={() => void detailQuery.refetch()}>
            Retry loading note
          </Button>
        </div>
      </div>
    );
  }

  if (detailQuery.isPending || !draft) {
    return (
      <div className="flex h-full flex-col">
        <div className="flex shrink-0 items-center gap-2 border-b border-border/50 px-3 py-2">
          <Button size="sm" variant="ghost" className="h-7 gap-1 px-2 text-xs" onClick={onBack}>
            <ArrowLeft className="size-3.5" /> Back
          </Button>
        </div>
        <div className="flex-1 space-y-2 p-3">
          <Skeleton className="h-8 w-full rounded-md" />
          <Skeleton className="h-7 w-1/2 rounded-md" />
          <Skeleton className="h-48 w-full rounded-md" />
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-center gap-2 border-b border-border/50 px-3 py-2">
        <Button
          size="sm"
          variant="ghost"
          className="h-7 gap-1 px-2 text-xs"
          onClick={onBack}
          title="Back to list"
        >
          <ArrowLeft className="size-3.5" /> Back
        </Button>
        <div className="ml-auto flex items-center gap-1">
          <div className="flex rounded-md border border-border/50 p-0.5">
            <button
              type="button"
              onClick={() => setViewMode('edit')}
              className={[
                'inline-flex h-6 items-center gap-1 rounded px-2 text-[11px] transition-colors',
                viewMode === 'edit'
                  ? 'bg-secondary text-foreground'
                  : 'text-muted-foreground hover:text-foreground',
              ].join(' ')}
            >
              <Pencil className="size-3" /> Edit
            </button>
            <button
              type="button"
              onClick={() => setViewMode('preview')}
              className={[
                'inline-flex h-6 items-center gap-1 rounded px-2 text-[11px] transition-colors',
                viewMode === 'preview'
                  ? 'bg-secondary text-foreground'
                  : 'text-muted-foreground hover:text-foreground',
              ].join(' ')}
            >
              <Eye className="size-3" /> Preview
            </button>
          </div>
          <AppendFromPagePanel
            getCurrentContent={() => draftRef.current?.content ?? ''}
            onAppend={onAppend}
          />
          <Button
            size="sm"
            variant="ghost"
            className="size-7 p-0 text-destructive"
            onClick={() => setDeleteOpen(true)}
            title="Delete note"
            disabled={deleting}
          >
            <Trash2 className="size-3.5" />
          </Button>
        </div>
      </div>

      <ConfirmDialog
        open={deleteOpen}
        onOpenChange={(next) => {
          if (!next) setDeleteOpen(false);
        }}
        title="Delete this note?"
        description="It will be marked deleted but is recoverable from the main app."
        confirmLabel="Delete"
        variant="destructive"
        busy={deleting}
        onConfirm={() => void performDelete()}
      />

      {deleteFailed && (
        <div
          className="flex shrink-0 items-center justify-between gap-2 border-b border-destructive/30 bg-destructive/5 px-3 py-2 text-xs"
          role="alert"
        >
          <span>Could not confirm deletion. This note remains open; check it before retrying.</span>
          <Button type="button" size="sm" variant="outline" onClick={() => setDeleteOpen(true)}>
            Retry delete
          </Button>
        </div>
      )}

      {detailQuery.isError && (
        <div
          className="flex shrink-0 items-center justify-between gap-2 border-b border-destructive/30 bg-destructive/5 px-3 py-2 text-xs"
          role="alert"
        >
          <span>Could not refresh this note. Your open draft is still here.</span>
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={() => void detailQuery.refetch()}
          >
            Retry loading note
          </Button>
        </div>
      )}

      <div className="flex shrink-0 flex-col gap-2 border-b border-border/50 px-3 py-2">
        <Input
          value={draft.label}
          onChange={(e) => updateDraft({ label: e.target.value })}
          placeholder="Untitled"
          className="h-8 border-0 bg-transparent px-0 text-base font-semibold focus-visible:ring-0 focus-visible:ring-offset-0"
        />
        <div className="flex items-center gap-2">
          <Input
            value={draft.folderName}
            onChange={(e) => updateDraft({ folderName: e.target.value })}
            placeholder="Folder"
            list={FOLDERS_LIST_ID}
            className="h-7 max-w-[200px] text-xs"
          />
          <datalist id={FOLDERS_LIST_ID}>
            {folderSuggestions.map((f) => (
              <option key={f} value={f} />
            ))}
          </datalist>
          <SaveStatus
            state={savingState}
            lastSavedAt={lastSavedAt}
            onRetry={() => {
              if (draftRef.current) void persist(draftRef.current);
            }}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        {viewMode === 'edit' ? (
          <Textarea
            value={draft.content}
            onChange={(e) => updateDraft({ content: e.target.value })}
            placeholder="Start writing… or use Append from page to capture content."
            className="h-full min-h-full w-full resize-none rounded-none border-0 bg-transparent px-3 py-2 font-mono text-xs leading-relaxed focus-visible:ring-0 focus-visible:ring-offset-0"
          />
        ) : draft.content.trim() ? (
          <div className="px-3 py-2 text-sm">
            <MarkdownView content={draft.content} />
          </div>
        ) : (
          <div className="px-3 py-12 text-center text-xs text-muted-foreground">
            Empty note. Switch to Edit to start writing.
          </div>
        )}
      </div>
    </div>
  );
}

function SaveStatus({
  state,
  lastSavedAt,
  onRetry,
}: {
  state: 'idle' | 'saving' | 'saved' | 'error' | 'unsaved';
  lastSavedAt: string | null;
  onRetry: () => void;
}) {
  if (state === 'saving') {
    return <span className="text-[10px] text-muted-foreground">Saving…</span>;
  }
  if (state === 'error' || state === 'unsaved') {
    return (
      <span className="text-[10px] text-destructive">
        {state === 'error' ? 'Save failed' : 'Unsaved changes'}{' '}
        <button type="button" onClick={onRetry} className="underline">
          Retry save
        </button>
      </span>
    );
  }
  if (lastSavedAt) {
    return (
      <span className="text-[10px] text-muted-foreground">
        Saved {formatRelativeTime(lastSavedAt)}
      </span>
    );
  }
  return null;
}
